setcpm(30) // 120 BPM

// --- Global Scale Helper ---
$SCALE_KEY: "c3:major";

// --- Chord Progression (I-vi-IV-V in C Major) ---
// I: Cmaj (0,2,4)
// vi: Amin (5,0,2) -- relative minor of 6th degree
// IV: Fmaj (3,5,7)
// V: Gmaj (4,6,8)
$CHORD_PROG_PADS: P("<[0,2,4] [5,0,2] [3,5,7] [4,6,8]>"); // Triads for pads

// --- Drum Patterns ---
$KICK_PATTERN: "bd*4"; // Steady kick for the deep-house groove
$CLAP_PATTERN: "~ cp ~ cp"; // Classic deep house clap on beats 2 & 4
$HATS_PATTERN: "[~ hh]*4"; // Off-beat 16ths for rhythmic texture

// --- Bass Pattern (Rhythmic scale-degree pattern, not a drone) ---
// Define individual 1-bar motifs for each chord root, relative to $SCALE_KEY
$BASS_MOTIF_C: P("<0 . 2 . 4 . 2 .>"); // For Cmaj (I)
$BASS_MOTIF_Am: P("<5 . 0 . 2 . 0 .>"); // For Amin (vi)
$BASS_MOTIF_F: P("<3 . 5 . 7 . 5 .>"); // For Fmaj (IV)
$BASS_MOTIF_G: P("<4 . 6 . 8 . 6 .>"); // For Gmaj (V)
// Concatenate the motifs to form the full 4-bar bass line (32 elements = 4 bars at 16th notes)
$BASS_LINE: P("<$BASS_MOTIF_C $BASS_MOTIF_Am $BASS_MOTIF_F $BASS_MOTIF_G>");

// --- Pad Pattern (Sustained chords for warmth and harmonic foundation) ---
$PAD_LINE: $CHORD_PROG_PADS; // Already a Pattern of chord degrees

// --- Lead Melody (A memorable motif with clear phrasing and space) ---
$LEAD_MOTIF_A: P("<4 . 2 . 0 . ~ ~>"); // 1-bar motif (G E C with breathing space)
$LEAD_MOTIF_B: P("<7 . 5 . 3 . ~ ~>"); // A related 1-bar motif (C A F with breathing space)
// The full lead line reuses and varies the motifs across the 4-bar progression
$LEAD_LINE: P("<$LEAD_MOTIF_A $LEAD_MOTIF_B $LEAD_MOTIF_A $LEAD_MOTIF_A.add(4)>"); // Concatenation of patterns, with octave variation

// --- Arrangement & Stacking (16 bars total, 4x 4-bar progressions) ---
stack(
  // 1. Kick Drum: Consistent rhythmic anchor, present throughout
  sound($KICK_PATTERN).gain(0.9).mask("<1@16>"), 

  // 2. Clap: Enters after an initial groove, defining the backbeat
  sound($CLAP_PATTERN).gain(0.7).decay(.1).mask("<0@4 1@12>"), 

  // 3. Hi-Hats: Continuous rhythmic shimmer
  sound($HATS_PATTERN).gain(0.6).decay(.05).mask("<1@16>"), 

  // 4. Bass Line: Warm, filtered sine providing rhythmic and harmonic pulse
  // Enters after 2 bars of drums to build the groove
  n($BASS_LINE).scale($SCALE_KEY).sine().lpf(800).gain(0.9).mask("<0@2 1@14>"), 

  // 5. Chord Pad: Lush, filtered sawtooth for sustained harmonic warmth and body
  // Enters with the bass for harmonic foundation
  n($PAD_LINE).scale($SCALE_KEY).sawtooth().lpf(1500).gain(0.7).attack(.1).decay(.8).sustain(.5).release(.5).room(0.6).mask("<0@2 1@14>"), 

  // 6. Lead Melody: Clear, filtered triangle with reverb and delay for space and definition
  // Enters halfway through the piece for a clear hook, then rests for space
  n($LEAD_LINE).scale("c4:major").triangle().lpf(3000).gain(0.8).decay(.4).sustain(.3).release(.2).room(.4).delay(0.3).delaytime(0.25).delayfeedback(0.5).mask("<0@8 1@8>") 
)

tempo: setcpm(30)
scale_helper = "c3:major" // Canonical I-vi-IV-V progression in C Major

// --- DRUMS ---
kick = sound("bd*4").gain(.9) // Punchy kick, sits clearly above synths
hh = sound("[~ hh]*4").gain(.6).lpf(12000) // Off-beat closed hats, lightly filtered
cp = sound("~ cp ~ cp").gain(.7) // Clap on 2 and 4
shaker = sound("white*16").decay(.01).sustain(0).gain(.2).hpf(8000) // Light, airy high-end

drums = stack(kick, hh, cp, shaker).mask("<1@4>") // Drums play throughout 4 cycles

// --- BASS ---
// Rhythmic scale-degree pattern locked to kick, follows I-vi-IV-V progression
// C(0) - Am(5) - F(3) - G(4) in C Major scale
// Each segment is a 1-bar pattern (4 quarter notes) repeated across 4 bars (16 quarter notes total)
bass_degrees = n("<0 ~ 0 2 ~ 0 4 ~ 5 ~ 5 6 ~ 5 2 ~ 3 ~ 3 4 ~ 3 0 ~ 4 ~ 4 5 ~ 4 1 ~>/16").scale(scale_helper)
bass_voice = sawtooth.lpf(400).lpq(1.2).gain(.6).decay(.1).sustain(.05) // Warm, filtered sawtooth bass

bass = bass_voice.n(bass_degrees).mask("<1@4>") // Bass plays throughout 4 cycles

// --- PAD (CHORDS) ---
// I-vi-IV-V progression: Cmaj (0,2,4), Am (5,0,2), Fmaj (3,5,0), Gmaj (4,6,1)
// Each chord held for 1 bar (4 beats)
pad_notes = n("<[0,2,4]@4 [5,0,2]@4 [3,5,0]@4 [4,6,1]@4>/16").scale(scale_helper)
pad_voice = sawtooth.lpf(1000).lpq(1.0).gain(.4).attack(.5).decay(1).sustain(1).release(.5).room(.5) // Warm, evolving pad with reverb

pad = pad_voice.n(pad_notes).mask("<1@1 0@1 1@2>") // Pad on for cycle 1, off for cycle 2 (space for lead), on for cycles 3 & 4

// --- LEAD MELODY (THE HOOK) ---
// Memorable motif with rests for space, follows I-vi-IV-V structure
// Pattern is 4 bars long (16 quarter notes)
lead_degrees = n("<(2 ~ 0 ~) (2 4 ~ ~) (5 ~ 4 ~) (5 0 ~ ~) (0 ~ 6 ~) (0 3 ~ ~) (1 ~ 2 ~) (1 4 ~ ~)>/16").scale(scale_helper)
lead_voice = triangle.lpf(1500).lpq(1.2).gain(.5).delay(.4).delaytime(.3).delayfeedback(.6).release(.4) // Filtered triangle with delay for atmosphere

lead = lead_voice.n(lead_degrees).mask("<0@1 1@1 0@1 1@1>") // Lead enters on cycle 2, drops for cycle 3, returns for cycle 4

// --- FINAL STACK ---
stack(drums, bass, pad, lead)

setcpm(30)

// Drums
KICK = sound("bd*4").gain(0.95) // 4 kicks per 4-beat cycle -> 16 kicks over 16 beats
CLAP = sound("~ cp ~ cp").gain(0.8).mask("<0@4 1@12>") // Clap enters after 4 beats, plays for 12 beats
HATS = sound("[~ hh]*4").gain(0.6).decay(0.05).mask("<0@4 1@12>") // Hats enter after 4 beats, play for 12 beats

// Bass (rhythmic scale-degree pattern, filtered sawtooth)
// I-vi-IV-V progression (C major)
// Each block is 4 beats, total 16 beats
BASS_PATTERN = "<0 ~ 0 ~> <5 ~ 5 ~> <3 ~ 3 ~> <4 ~ 4 ~>"
BASS = n(BASS_PATTERN).scale("c2:major").sound("sawtooth").lpf(800).lpq(0.5).gain(0.8).mask("<0@2 1@14>") // Bass enters after 2 beats, plays for 14 beats

// Chords/Pad (sustained, filtered sawtooth)
// I-vi-IV-V progression (C major), each chord held for 4 beats
CHORD_PROGRESSION = "<[0,2,4]/4 [5,0,2]/4 [3,5,0]/4 [4,6,1]/4>" // Total 16 beats
PAD = n(CHORD_PROGRESSION).scale("c3:major").sound("sawtooth").lpf(1200).lpq(0.6).gain(0.6).room(0.5).mask("<0@4 1@12>") // Pad enters after 4 beats, plays for 12 beats

// Lead Melody (memorable motif with space, filtered triangle)
// 16-beat motif with clear phrasing and rests
LEAD_MOTIF = "<0 ~ 2 ~ 4 ~ 5 ~ 4 ~ 2 ~ 0 ~ ~ ~ ~ ~ ~>" // Each element is 1 beat, total 16 beats
LEAD = n(LEAD_MOTIF).scale("c4:major").sound("triangle").lpf(2000).lpq(0.8).gain(0.7).delay(0.4).delayfeedback(0.6).room(0.3).mask("<0@8 1@8>") // Lead enters after 8 beats, plays for 8 beats

stack(
  KICK,
  CLAP,
  HATS,
  BASS,
  PAD,
  LEAD
)
